package com.wizzadrds.theworldremembers.rumor; import com.mojang.serialization.Codec; import com.mojang.serialization.codecs.RecordCodecBuilder; import net.minecraft.core.UUIDUtil; import java.util.UUID; import com.wizzadrds.theworldremembers.memory.MemoryEventType; public record KnowledgeFact(UUID subject, MemoryEventType eventType,long eventTime,UUID source,KnowledgeOrigin origin,int confidence,long lastUpdatedTick){public KnowledgeFact{if(confidence<0||confidence>100)throw new IllegalArgumentException("confidence");} public static final Codec<KnowledgeFact> CODEC=RecordCodecBuilder.create(i->i.group(UUIDUtil.CODEC.fieldOf("subject").forGetter(KnowledgeFact::subject),Codec.STRING.xmap(MemoryEventType::valueOf,MemoryEventType::name).fieldOf("eventType").forGetter(KnowledgeFact::eventType),Codec.LONG.fieldOf("eventTime").forGetter(KnowledgeFact::eventTime),UUIDUtil.CODEC.fieldOf("source").forGetter(KnowledgeFact::source),Codec.STRING.xmap(KnowledgeOrigin::valueOf,KnowledgeOrigin::name).fieldOf("origin").forGetter(KnowledgeFact::origin),Codec.INT.fieldOf("confidence").forGetter(KnowledgeFact::confidence),Codec.LONG.fieldOf("lastUpdatedTick").forGetter(KnowledgeFact::lastUpdatedTick)).apply(i,KnowledgeFact::new)); public KnowledgeFact degrade(long tick){long age=Math.max(0,tick-lastUpdatedTick);int rate=origin==KnowledgeOrigin.RUMORED?2:1;return new KnowledgeFact(subject,eventType,eventTime,source,origin,Math.max(0,confidence-(int)(age/24000)*rate),lastUpdatedTick);} public KnowledgeFact reported(long tick){KnowledgeOrigin next=origin==KnowledgeOrigin.DIRECT?KnowledgeOrigin.REPORTED:KnowledgeOrigin.RUMORED;return new KnowledgeFact(subject,eventType,eventTime,source,next,Math.max(20,confidence-(next==KnowledgeOrigin.RUMORED?15:10)),tick);} }
